 /** Selects paths with an ordered list of glob patterns. See README.md for the syntax. */
 export class PathMatcher {
+  private readonly compiledPatterns: CompiledPattern[];
+
   constructor(patterns: string[]) {
-    throw new Error("not implemented");
+    this.compiledPatterns = patterns.map((pattern) => compilePattern(pattern));
   }

   /** Whether `path` is selected. */
   matches(path: string): boolean {
-    throw new Error("not implemented");
+    const decision = this.findDecision(path);
+    return decision ? !decision.negated : false;
   }

   /** The selected paths, in their original order. */
   filter(paths: string[]): string[] {
-    throw new Error("not implemented");
+    return paths.filter((path) => this.matches(path));
   }

   /** The pattern that decided about `path`, or null when none matches. */
   explain(path: string): string | null {
-    throw new Error("not implemented");
+    return this.findDecision(path)?.original ?? null;
+  }
+
+  private findDecision(path: string): CompiledPattern | null {
+    const pathSegments = splitPath(path);
+    let decision: CompiledPattern | null = null;
+
+    for (const pattern of this.compiledPatterns) {
+      if (matchesSegments(pathSegments, pattern.segments)) {
+        decision = pattern;
+      }
+    }
+
+    return decision;
   }
 }
+
+type CompiledSegment =
+  | { kind: "globstar" }
+  | { kind: "segment"; regex: RegExp };
+
+type Compil
